import { describe, expect, it } from "vite-plus/test";
import type { Entry } from "../src/core/entries";
import { reduceComposition, formatFormula, parseFormula } from "../src/core/formula";
import { computeProfile } from "../src/core/profile";

/** Generated by `uv run reaction-voltage-calculator` (pymatgen PhaseDiagram.get_element_profile). */
interface Fixture {
  name: string;
  ion: string;
  entries: Entry[];
  cases: {
    formula: string;
    eAboveHull: number | null;
    profile: { x: number; mu: number; phases: string[] }[];
  }[];
}

const fixtures = Object.values(
  import.meta.glob<Fixture>("./fixtures/*.json", { eager: true, import: "default" }),
);

/** Order-independent key of a phase name (pymatgen and MP may order elements differently). */
const key = (name: string) => {
  const comp = reduceComposition(parseFormula(name)).reduced;
  return formatFormula(comp, Object.keys(comp).sort());
};

describe.each(fixtures.map((f) => [f.name, f] as const))("pymatgen fixture %s", (_name, fx) => {
  it.each(fx.cases.map((c) => [c.formula, c] as const))("%s", (_formula, c) => {
    const p = computeProfile({ entries: fx.entries, formula: c.formula, ion: fx.ion });
    expect(p.regions).toHaveLength(c.profile.length);
    p.regions.forEach((r, i) => {
      const ref = c.profile[i];
      expect(r.x).toBeCloseTo(ref.x, 6);
      expect(r.muMax).toBeCloseTo(ref.mu, 6);
      const charge = ({ Li: 1, Na: 1, Mg: 2, Ca: 2 } as Record<string, number>)[fx.ion];
      if (charge) expect(r.vMin).toBeCloseTo(-ref.mu / charge, 6);
      expect(r.phases.map((ph) => key(ph.entry.name)).sort()).toEqual(ref.phases.map(key).sort());
      for (const el of p.elements) {
        const amount = r.phases.reduce(
          (sum, ph) => sum + ph.amount * (parseFormula(ph.entry.name)[el] ?? 0),
          0,
        );
        expect(amount).toBeCloseTo(el === fx.ion ? r.ionAmount : (p.target[el] ?? 0), 6);
      }
    });
    if (c.eAboveHull !== null) expect(p.eAboveHull).toBeCloseTo(c.eAboveHull, 6);
  });
});
